import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0514_3/projects/gen-depth-fingerprint/registry.yaml') as f:
    data = yaml.safe_load(f)

exps = data.get('experiments', {})
if isinstance(exps, dict):
    for rid, e in exps.items():
        if isinstance(e, dict):
            name = e.get('name', rid)
            status = e.get('status', 'N/A')
            conclusion = e.get('conclusion', '')
            desc = e.get('description', '')[:90]
            print(f'{rid:40s} | {status:12s} | {conclusion:10s} | {desc}')
        else:
            print(f'{rid}: {e}')
elif isinstance(exps, list):
    for e in exps:
        if isinstance(e, dict):
            rid = e.get('registry_id', 'N/A')
            name = e.get('name', rid)
            status = e.get('status', 'N/A')
            conclusion = e.get('conclusion', '')
            desc = e.get('description', '')[:90]
            print(f'{rid:40s} | {status:12s} | {conclusion:10s} | {desc}')
        else:
            print(f'item: {e}')
else:
    print(f'Type: {type(exps)}')
    print(list(data.keys()))
